"""Trace all deliverables to indexed raw facts and the exact recurrence."""
import argparse,csv,json
from fractions import Fraction
from pathlib import Path
from common import *

def save(p,x):p.write_text(json.dumps(x,indent=2)+'\n',encoding='utf8')
def main():
    p=argparse.ArgumentParser();p.add_argument('--public',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();data,_=load_data(a.public);policy=json.loads((ROOT/'policy.json').read_text(encoding='utf8'))
    support={};visible=histories(data)
    for path in data['scenarios']:
        for t,key in enumerate(visible[path['id']]):
            if key not in support:support[key]={'node':len(support),'week':t,'history':json.loads(key),'paths':[],'probability_mass':Fraction(),'action':action_at(policy,path['id'],t)}
            support[key]['paths'].append(path['id']);support[key]['probability_mass']+=Fraction(path['probability_numerator'],data['probability_denominator'])
    nodes=[dict(v,probability_mass=str(v['probability_mass'])) for v in support.values()];save(a.out/'information-nodes.json',nodes)
    sources={}
    for f in sorted((a.public/'inputs').glob('*.csv')):
        with f.open(encoding='utf8',newline='') as h:r=csv.DictReader(h);rows=list(r)
        sources[f.name]={'rows':len(rows),'columns':r.fieldnames,'identity_rule':'explicit index columns for array identity; otherwise complete business-key join; physical CSV row order unused'}
    source_map={'format':'l06-source-map/1','input_scope':'provided public directory only; copied originals are retained by actual public exercise','indexed_arrays':{k:data[k] for k in ('raw_materials','products','plants')},'supplier_order':[s['id'] for s in data['suppliers']],'path_order':[s['id'] for s in data['scenarios']],'sources':sources,'facility':'inputs/facility.json sets horizon, capacities, initial cash, credit and lag; tree-contract.json sets information semantics; OPERATIONS.md sets terminal rules','normalized_complete_values':'outputs/normalized-input.json','relations':{'order_units':'order_lots[node,s,m] * supplier_quotes[supplier_id,raw_id].pack_units','purchase':'sum(order_units * supplier_quotes.unit_price_minor), charged at order week','freight':'sum(truck_on * supplier_terms.freight_minor), including any empty on truck','due_arrival':'order week + supplier_terms.lead_weeks, unaffected by later capacity announcements','supplier_volume':'sum(order_units * raw_materials.volume), between minimum_volume*truck and current supplier_capacity.volume*truck','production':'production[node,plant,product] restricted by routes.allowed; shared sum(count*products.hours)<=plant_capacity.hours','BOM_consumption':'sum(made[product]*bom[product_id,raw_id].units)','raw_peak':'sum((prior raw + historical due arrivals + lead0 purchases)*raw_materials.volume), before consumption','finished_peak':'sum((prior finished + made)*products.volume), before current delivery','holding':'end-week raw * raw holding + end-week finished * product holding, no salvage','sales_receivable':'sum(current demand.units*products.sales_price_minor), due at original delivery week + facility.receipt_lag_weeks','cash':'prior cash + original due historical receipts - current purchase - freight - production - holding','cost':'sum purchase/freight/production/holding, excludes receipts and terminal receivables','expected':'sum(path cost * scenarios.probability_numerator/facility.probability_denominator)'},'source_code':{'programme/actor.py':'current packet validation, committed exact replay, history-index selection and logical request identity; spot current-needs action','programme/l06_packet.py':'unchanged public CSV explicit-index and complete-key parser','programme/l06_input.py':'unchanged public schema/strict integer input contracts','programme/l06_physics.py':'unchanged public single weekly recurrence','programme/check_l06.py':'unchanged public physical tensor audit','programme/tree_business.py':'unchanged public full event history, causality audit, committed replay and receipts','source/optimize.py':'CP-SAT history-node extensive form, fixed optimization seed; no actual selected future input','source/deliver.py':'exact ledgers, receivables, rational components and independent analytical relaxation','source/check_contracts.py':'focused positive business/protocol/error checks and actual invalid stdio attempt','source/verify_evidence.py':'cross-check deliverables against actual native journals and receipts','source/figures.py':'actual figures from generated exact ledgers','source/report.py':'readable business/report generation','source/recover_demo.py':'read-only checkpoint backup and actual native remaining-week restore demonstration','source/run_comparison.py':'retains original canonical wrapper failure and verifies explicit business-valid quality-rejection contract','source/package_spot.py':'generated compact capsule using the same actor source in spot mode','reproduce.ps1':'tested complete Windows operator reproduction command with fresh evidence folders'},'copied_public_code_provenance':'All five public business modules were copied without source edits from public/exercise-tools; these contain no candidate/reference solver. Runtime imports project copies and reads only supplied public facts. Native controller evidence retains separately copied original sources.','outputs':{'policy.json':'full-path expansion of the one shared-node solution; action tensors use strict JSON integers','programme/policy.json':'deployment copy of the same declared policy, checked by action equality against root and native journal','outputs/information-nodes.json':'complete histories, probability masses and actions; 60 nodes','outputs/commitment-policy.csv':'128 path/week grids x (3 trucks + 12 orders + 8 production) = 2944 rows, including zeros','outputs/weekly-ledger.csv':'128 path/week rows, exact public recurrence checked against actual journal','outputs/detailed-ledger.json':'raw/finished states, arrivals, made, consumption, hours, supplier volumes and full terminal queues','outputs/summary.json':'exact rational expected figures plus truthful native/optimization provenance','outputs/receivables.json':'all paths; original absolute due weeks16..19; receivables excluded from current cash','outputs/information-relaxation.json':'exact independently justified optimistic material/production lower bound','evidence/native-policy-01/':'actual policy source/argv/current stdin-output/native PID/commit73/restart/journal/checker','evidence/native-spot-01/':'actual spot execution, then expected quality-stage rejection retained in owner-error.json'}}
    save(ROOT/'source-map.json',source_map)
    detailed=json.loads((a.out/'detailed-ledger.json').read_text(encoding='utf8'));profiles=[]
    for path in data['scenarios']:
        name=path['id'];rows=detailed[name]['weeks'];d=policy['decisions'][name]
        suppliers={}
        for s,rule in enumerate(data['suppliers']):
            suppliers[rule['id']]={'trucks':sum(d['truck_on'][t][s] for t in range(data['weeks'])),'raw_units':[sum(d['order_lots'][t][s][m]*rule['pack_units'][m] for t in range(data['weeks'])) for m in range(4)],'purchase_cost':sum(d['order_lots'][t][s][m]*rule['pack_units'][m]*rule['price_minor'][m] for t in range(data['weeks']) for m in range(4))}
        profiles.append({'path':name,'suppliers':suppliers,'minimum_cash_week':min(rows,key=lambda r:r['cash'])['week'],'maximum_raw_peak_week':max(rows,key=lambda r:r['raw_stage_peak_volume'])['week'],'maximum_product_peak_week':max(rows,key=lambda r:r['product_stage_peak_volume'])['week'],'final_raw':detailed[name]['terminal_state']['raw'],'final_finished':detailed[name]['terminal_state']['finished']})
    save(a.out/'operations-profile.json',profiles)
    print(json.dumps({'nodes':len(nodes),'weekly_rows':128,'commitment_coordinates':2944,'source_tables':len(sources)}))
if __name__=='__main__':main()
